WITH scored AS (SELECT *, NTILE(3) OVER (ORDER BY rating ASC, id ASC) AS rating_bucket, ROW_NUMBER() OVER (ORDER BY rating ASC, id ASC) AS seq_no, LAST_VALUE(rating) IGNORE NULLS OVER (PARTITION BY city ORDER BY rating ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_rating, LEAD(rating, 1, 0) OVER (PARTITION BY country ORDER BY rating ASC, id ASC) AS next_rating FROM suppliers) SELECT id, supplier_name, country, city, rating, rating_bucket, seq_no, last_known_rating, next_rating, CASE WHEN country RLIKE '^(TH|DE)$' THEN 'OTHER_ZONE' WHEN country RLIKE '^(US|SG)$' THEN 'CORE' ELSE 'GROUP_B' END AS country_zone FROM scored ORDER BY next_rating DESC NULLS LAST, country DESC
